-- Les etats, dans l'ordre. `date_figee` marque le figement des recettes.
UPDATE plan_production SET statut = 'SIMULATION' WHERE id_plan = '5c0866c3-6db9-4a35-843c-a65ee9fda888' AND statut = 'BROUILLON';
UPDATE plan_qualite SET date_figee = to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
 WHERE id_plan = '5c0866c3-6db9-4a35-843c-a65ee9fda888' AND date_figee IS NULL;
-- La mise en service dit QUI valide et QUAND : la base l'exige (check3), et
-- un plan qui alimente le MRP sans porteur ne se defend pas.
UPDATE plan_production
   SET statut = 'EN_COURS',
       date_validation = to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
       id_utilisateur_validation = (SELECT id_utilisateur FROM utilisateur WHERE login = 'admin'),
       date_modification = to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
       id_utilisateur_modification = (SELECT id_utilisateur FROM utilisateur WHERE login = 'admin')
 WHERE id_plan = '5c0866c3-6db9-4a35-843c-a65ee9fda888' AND statut = 'SIMULATION';

-- Le MRP, par la vue — les recettes de cette base, pas celles du poste.
DELETE FROM besoin_mrp WHERE id_plan = '5c0866c3-6db9-4a35-843c-a65ee9fda888';
INSERT INTO besoin_mrp
    (id_plan, mois, rang_mois, annee_mois, code_reference, quantite_brute_kg,
     taux_perte_applique, quantite_kg, date_calcul, date_reference)
SELECT id_plan, mois, rang_mois, annee_mois, code_reference, quantite_brute_kg,
       taux_perte_pct, quantite_kg,
       to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
       to_char(current_date, 'YYYY-MM-DD')
  FROM v_besoin_mrp_calcule WHERE id_plan = '5c0866c3-6db9-4a35-843c-a65ee9fda888';

DO $$
DECLARE n bigint;
BEGIN
    SELECT count(*) INTO n FROM besoin_mrp WHERE id_plan = '5c0866c3-6db9-4a35-843c-a65ee9fda888';
    IF n = 0 THEN
        RAISE EXCEPTION 'aucun besoin calcule : les recettes de cette base sont-elles chargees ?';
    END IF;
    RAISE NOTICE 'besoins calcules : % lignes', n;
END $$;

COMMIT;
